            clamped_cents_q8 = cents_q8;

        // 算术右移向负无穷取整。例：-0.25 音分分解为 -1 + 192/256。
        whole_cents = clamped_cents_q8 >>> 8;
        fraction_q8 = clamped_cents_q8[7:0];
        lower_index = 10'(whole_cents + 18'sd300);
        upper_index = (lower_index < 10'd600) ? lower_index + 10'd1 : 10'd600;
        lower_ratio = ratio_at(lower_index);
        upper_ratio = ratio_at(upper_index);
        ratio_delta = upper_ratio - lower_ratio;
        fractional_product = ratio_delta * fraction_q8;
        rounded_fraction = (fractional_product + 29'd128) >> 8;
        ratio_q20 = lower_ratio + 21'(rounded_fraction);
    end
